async function toggleRecording(){if(recorder&&recorder.state==='recording'){recorder.stop();return}if(!window.MediaRecorder){toast('הקלטה אינה נתמכת במכשיר הזה');return}if(!navigator.mediaDevices?.getDisplayMedia){toast('הקלטת כל מסך האפליקציה אינה נתמכת בגרסת Android/WebView זו. נדרשת הרשאת הקלטת מסך של Android.');return}try{const display=screenStream||await navigator.mediaDevices.getDisplayMedia({video:{frameRate:15},audio:true});screenStream=display;const tracks=[...display.getVideoTracks()];if(!tracks.length)throw new Error('לא התקבל מסך להקלטה');if(localStream)localStream.getAudioTracks().filter(t=>t.enabled).forEach(t=>tracks.push(t));remoteStreams.forEach(st=>st.getAudioTracks().filter(t=>t.readyState==='live').forEach(t=>{if(!tracks.includes(t))tracks.push(t)}));const recordStream=new MediaStream(tracks);recordChunks=[];recorder=new MediaRecorder(recordStream);const filename='IsraMeet-Screen-'+new Date().toISOString().replace(/[:.]/g,'-')+'.webm';recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};recorder.onstop=()=>{const blob=new Blob(recordChunks,{type:recorder.mimeType||'video/webm'});const id=uid();recordings.unshift({id,title:(activeMeeting?.title||'פגישה')+' — הקלטת מסך',date:new Date().toISOString(),size:(blob.size/1024/1024).toFixed(1)+' MB',filename});save('isrameet.recordings',recordings);storeRecording(id,blob).then(()=>toast('הקלטת המסך נשמרה בהקלטות')).catch(()=>toast('לא ניתן לשמור את הקובץ בספריית ההקלטות'));const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);display.getTracks().forEach(t=>t.stop());screenStream=null;$('#record-label')&&($('#record-label').textContent='הקלטה')};tracks[0].addEventListener('ended',()=>{if(recorder?.state==='recording')recorder.stop()},{once:true});recorder.start(1000);$('#record-label')&&($('#record-label').textContent='עצור הקלטה');toast('הקלטת המסך התחילה. אשר את בקשת Android וודא הסכמה של המשתתפים.')}catch(e){toast('הקלטת מסך לא התחילה: '+(e.message||'הפעולה בוטלה'))}}
async function shareScreen(){if(!navigator.mediaDevices?.getDisplayMedia){toast('שיתוף מסך אינו נתמך בגרסת Android/WebView זו');return}try{const display=await navigator.mediaDevices.getDisplayMedia({video:true});const track=display.getVideoTracks()[0];screenStream=display;const video=$('#local-video');if(video)video.srcObject=display;mediaCalls.forEach(call=>{try{const sender=call.peerConnection?.getSenders().find(s=>s.track?.kind==='video');if(sender)sender.replaceTrack(track)}catch{}});track.onended=()=>{if(video&&localStream)video.srcObject=localStream;screenStream=null};toast('שיתוף המסך התחיל')}catch(e){toast('שיתוף המסך בוטל או אינו זמין')}}
document.addEventListener('submit',async e=>{const form=e.target;if(form.id==='meeting-form'){e.preventDefault();const f=new FormData(form),type=form.dataset.type;if(type==='join'){const code=String(f.get('code')||'').trim().toUpperCase().replace(/[^A-Z0-9-]/g,'');if(code.length<4){toast('הזן קוד פגישה תקין');return}const m=meetings.find(x=>x.code===code)||{id:uid(),title:'פגישה שהצטרפת אליה',code};startRoom(m,false);return}const title=String(f.get('title')||'').trim();if(!title){toast('נא להזין שם לפגישה');return}let when=null;if(type==='schedule'){when=new Date(f.get('when')).toISOString();if(new Date(when)<=new Date()){toast('יש לבחור זמן עתידי');return}}const m={id:uid(),title,code:uid(),when,createdAt:new Date().toISOString(),owner:user?.email||null};meetings.unshift(m);save('isrameet.meetings',meetings);if(when){await scheduleNotification(m);toast('הפגישה נקבעה');tab='יומן';go('home')}else{try{await Share.share({title:'הזמנה לפגישת IsraMeet',text:`הצטרפו לפגישה: ${m.title}
קוד: ${m.code}`})}catch{}startRoom(m,true)}return}if(form.id==='auth-form'){e.preventDefault();const f=new FormData(form),email=String(f.get('email')||'').trim().toLowerCase(),password=String(f.get('password')||''),mode=form.dataset.mode;if(mode==='login'){const accounts=read('isrameet.accounts',{}),account=accounts[email];if(!account||account.passwordHash!==await passwordHash(password)){toast('האימייל או הסיסמה אינם נכונים במכשיר זה');return}user={name:account.name,email};save('isrameet.user',user);toast('התחברת בהצלחה');tab='פרופיל';go('home');return}const name=String(f.get('name')||'').trim();if(!name||password.length<6||!email){toast('נא למלא את כל השדות');return}const accounts=read('isrameet.accounts',{});if(accounts[email]){toast('כבר קיים משתמש עם האימייל הזה במכשיר. נסה להתחבר.');return}accounts[email]={name,email,passwordHash:await passwordHash(password),createdAt:new Date().toISOString()};save('isrameet.accounts',accounts);user={name,email};save('isrameet.user',user);toast('המשתמש נוצר במכשיר הזה');tab='פרופיל';go('home');return}if(form.id==='message-form'){e.preventDefault();const f=new FormData(form);messages.unshift({id:uid(),title:String(f.get('title')).trim(),text:String(f.get('text')).trim(),date:dateText(new Date())});save('isrameet.messages',messages);tab='הודעות';go('home');toast('ההודעה נשמרה');return}if(form.id==='room-chat-form'){e.preventDefault();const textValue=String(new FormData(form).get('text')||'').trim(),file=$('#room-chat-image')?.files?.[0];if(!textValue&&!file)return;let imageData=null;if(file){if(!file.type.startsWith('image/')){toast('אפשר לשלוח תמונות בלבד');return}if(file.size>1500000){toast('התמונה גדולה מדי. בחר תמונה עד 1.5MB');return}imageData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)})}const payload={type:'chat',name:user?.name||'משתתף',text:textValue,imageData};appendRoomChat(payload.name,textValue,imageData);dataConnections.forEach(c=>{if(c.open)c.send(payload)});form.reset();toast(dataConnections.size?'ההודעה נשלחה למשתתפים':'ההודעה נוספה לצ׳אט המקומי');return}});
