try{const raw=new URLSearchParams(location.search).get('invite');if(raw)decodeInvite(raw)}catch{}const handleInviteUrl=url=>{try{const u=new URL(url),raw=u.searchParams.get('data')||u.searchParams.get('invite');if(raw){decodeInvite(raw);view=user?'home':'auth';render()}}catch{}};App.addListener('appUrlOpen',e=>handleInviteUrl(e.url));App.getLaunchUrl().then(r=>{if(r?.url)handleInviteUrl(r.url)}).catch(()=>{});view='splash';render();setTimeout(()=>{if(view==='splash'){view=user?'home':'auth';render()}},2800);document.addEventListener('timeupdate',e=>{if(e.target?.id==='recording-player-video')updatePlayerClock()});document.addEventListener('loadedmetadata',e=>{if(e.target?.id==='recording-player-video')updatePlayerClock()});document.addEventListener('input',e=>{if(e.target?.id==='recording-timeline'){const v=$('#recording-player-video');if(v&&Number.isFinite(v.duration))v.currentTime=v.duration*Number(e.target.value)/1000}});
